package com.novacommerce.inventory.infrastructure.security;
import jakarta.servlet.http.*; import org.springframework.security.oauth2.server.resource.web.*; import org.springframework.stereotype.Component;
@Component public class CookieBearerTokenResolver implements BearerTokenResolver {private final DefaultBearerTokenResolver header=new DefaultBearerTokenResolver(); public String resolve(HttpServletRequest request){String token=header.resolve(request);if(token!=null)return token;Cookie[] cookies=request.getCookies();if(cookies!=null)for(Cookie cookie:cookies)if("NC_ACCESS".equals(cookie.getName()))return cookie.getValue();return null;} }
